mapper.select:
UPDATE nfc_tag_keys SET provisioning_exported_at = #{now}
WHERE tag_id = #{tagId} AND status = 'PENDING' AND provisioning_exported_at IS NULL
RETURNING id, key_version, app_master_key_enc, meta_read_key_enc, file_read_key_enc

SELECT id, stage, outcome, reason, counter, counter_gap, customer_id, created_at
FROM tap_events
WHERE tag_id = #{tagId}
ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}
